def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    cells_by_color = {
        color: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for color in range(1, 10)
    }
    anchor = min(r for r, c in cells_by_color[8])
    for color, cells in cells_by_color.items():
        if not cells:
            continue
        shift = min(r for r, c in cells) - anchor
        for r, c in cells:
            nr = r - shift
            if 0 <= nr < h:
                out[nr][c] = color
    return out
